ceiling = 100000000;
const endpointBits = P.map((_, i) =>
  G.filter(([u]) => u === i).reduce((bits, [, , bit]) => bits | bit, 0n)
);
const directions = [[0n,1n],[1n,17n],[1n,0n],[1n,4n],[2n,5n],[1n,9n],[3n,17n],[1n,1n],[19n,28n],[1n,30n],[3n,77n],[3n,40n],[3n,1n],[3n,38n],[3n,53n],[2n,73n],[1n,11n]];
const groups = directions.map(([T,U]) => P
  .flatMap(([t,b,d], id) => {
    if (id === 24 || T*b !== U*t) return [];
    const r = T ? t/T : b/U;
    if (r <= 0n || t !== r*T || b !== r*U || d < 0n) throw Error("invalid ordinate");
    return [{id, r, d, threshold: [-T*d*r, -3n*U*d*r, -3n*d*d+(68n*T+33n*U)*d*r, 3n*r*r]}];
  })
  .sort((a,b) => sg(a.d*b.r-b.d*a.r))
);
if (P[24].join() !== "0,0,1" || new Set(groups.flat().map(x => x.id)).size !== 50) throw Error("endpoint coverage");
if (groups.some(g => g.some((x, i) => i && x.d*g[i-1].r <= g[i-1].d*x.r))) throw Error("duplicate ordinate");
const interceptRows = directions.map(([T,U]) => [T*T,T*U,U*U]);
const circuits = directions.map((_,k) => {
  const tests = [];
  for (let i=0;i<k;i++) for (let j=i+1;j<k;j++) for (let h=j+1;h<k;h++) {
    const indices = [i,j,h,k];
    const weights = indices.map((_, a) => {
      const [x,y,z] = indices.filter((_,b) => a!==b).map(o => interceptRows[o]);
      return (a%2 ? -1n : 1n) * dot(x, cross(y,z));
    });
    if (weights.some(w => !w) || [0,1,2].some(
      a => indices.reduce((s,o,j) => s+weights[j]*interceptRows[o][a],0n)
    )) throw Error("invalid intercept circuit");
    tests.push({indices,weights});
  }
  return tests;
});

function patterns(members) {
  const words = [];
  for (let j=0;j<=members.length;j++) {
    for (const zero of (j===members.length ? [false] : [false,true])) {
      const positiveFrom = j+Number(zero);
      let p=0n, n=0n;
      for (let i=0;i<j;i++) n |= endpointBits[members[i].id];
      for (let i=positiveFrom;i<members.length;i++) p |= endpointBits[members[i].id];
      const anchor = zero ? members[j].threshold : null;
      words.push({p,n,zero, lower:anchor??members[positiveFrom]?.threshold??null,
                            upper:anchor??members[j-1]?.threshold??null});
    }
  }
  return words;
}

function sumBound(indices, weights, words, side) {
  let sum = [0n,0n,0n,1n];
  for (let j=0;j<4;j++) {
    const weight = weights[j]*side;
    const part = words[indices[j]][weight>0n ? "upper" : "lower"];
    if (!part) return null;
    const values = [0,1,2].map(i => sum[i]*part[3]+part[i]*sum[3]*weight);
    sum = [...values, sum[3]*part[3]];
    const divisor = sum.reduce(gcd,0n);
    sum = sum.map(x => x/divisor);
  }
  return sum.slice(0,3);
}

// All rays are nonnegative and represent points with e+f+c=1.
function clip(poly, row) {
  const values=poly.map(v => dot(v,row));
  if (values.every(v => v>=0n)) return poly;
  const out=[];
  for (let j=0;j<poly.length;j++) {
    const k=(j+1)%poly.length;
    if (values[j]>=0n) out.push(poly[j]);
    if (values[j]*values[k]<0n) {
      const a=values[j]>0n ? j : k;
      const b=values[j]>0n ? k : j;
      out.push(norm(poly[b].map((x,i) => values[a]*x-values[b]*poly[a][i])));
    }
  }
  return [...new Map(out.map(v => [v.join(),v])).values()];
}

let states=[{a:endpointBits[24],b:0n,words:[],
             polygon:clip([[1n,0n,0n],[0n,1n,0n],[0n,0n,1n]],[1n,51n,-536n]),
             strict:[[1n,0n,0n],[0n,1n,0n],[0n,0n,1n],[1n,51n,-536n]]}];
const stages=[];
for (let k=0;k<groups.length;k++) {
  const out=[];
  const stage={visits:0,direct:0,algebra:0,capacity:0,survivors:0,before:checks};
  for (const state of states) for (const word of patterns(groups[k])) {
    stage.visits++;
    const a=state.a|word.p;
    const b=state.b|word.n;
    if (count(a)>31 || count(b)>31) {stage.direct++;continue;}
    const words=[...state.words,word];
    let polygon=state.polygon;
    const strict=[...state.strict];
    for (const {indices,weights} of circuits[k]) {
      const singleton = indices.every(i => words[i].zero);
      for (const side of [1n,-1n]) {
        const row = sumBound(indices,weights,words,side);
        if (!row) continue;
        polygon=clip(polygon,row);
        if (!polygon.length || !singleton && polygon.every(v => dot(v,row)===0n)) {
          polygon=[];
          break;
        }
        if (!singleton && polygon.some(v => dot(v,row)===0n)) strict.push(row);
      }
      if (!polygon.length) break;
    }
    if (!polygon.length || strict.some(row => polygon.every(v => dot(v,row)===0n))) {
      stage.algebra++;
      continue;
    }
    if (!can(a,5) || !can(b,5)) {stage.capacity++;continue;}
    out.push({a,b,words,polygon,strict:strict.filter(row => polygon.some(v => dot(v,row)===0n))});
  }
  stage.survivors=out.length;
  stage.checks=checks-stage.before;
  delete stage.before;
  stages.push(stage);
  states=out;
}
return {endpoints:P.length,germs:G.length,linearMasks:Q.length,checks,stages,
        final:states.map(x => ({a:x.a.toString(16),b:x.b.toString(16),vertices:x.polygon.map(v=>v.map(String))}))};

