ceiling=100000000;
const endpointBits=P.map((_,i)=>G.filter(([u])=>u===i).reduce((s,[,,b])=>s|b,0n));
function tangentPatterns(p, a, b) {
  const x=P[p];
  const pivot=x.findIndex(y=>y>0n);
  const axes=[0,1,2].filter(j=>j!==pivot);
  const rows=G.filter(([u])=>u===p).map(([,v,bit])=>({
    bit, end:v, row:axes.map(j=>x[pivot]*P[v][j]-x[j]*P[v][pivot])
  }));
  if (rows.some(x=>!x.row.some(Boolean))) throw Error("collinear projective rays");
  const words=new Map();
  function put(lead,perturb) {
    let plus=0n, minus=0n;
    for(const {bit,end,row} of rows) {
      let sign=sg(row[0]*lead[0]+row[1]*lead[1]);
      if (!sign && perturb) sign=sg(row[0]*perturb[0]+row[1]*perturb[1]);
      if (!sign) {
        if (endpointBits[end]&a) sign=1;
        else if (endpointBits[end]&b) sign=-1;
        else return; // full-rank conic cannot have a line of zeros
      }
      if(sign>0) plus|=bit;
      else minus|=bit;
    }
    words.set(plus+","+minus,[plus,minus]);
  }
  for (const {row:[a,b]} of rows) for (const s of [-1n,1n]) {
    const lead=[s*b,-s*a];
    put(lead,null);
    put(lead,[a,b]);
    put(lead,[-a,-b]);
  }
  return [...words.values()];
}
let visits=0, direct=0, capacity=0;
const final=new Map();
const histogram={};
for (const {a:aa,b:bb} of upstream.final) {
  const a=BigInt("0x"+aa), b=BigInt("0x"+bb);
  const zs=P.map((_,i)=>i).filter(i=>!(endpointBits[i]&(a|b)));
  histogram[zs.length]=(histogram[zs.length]??0)+1;
  const bank=zs.map(p=>tangentPatterns(p,a,b)).sort((x,y)=>x.length-y.length);
  let current=[[a,b]];
  for (const words of bank) {
    const next=new Map();
    for (const [x,y] of current) for (const [p,n] of words) {
      visits++;
      const c=x|p, d=y|n;
      if (count(c)>31||count(d)>31) {direct++;continue;}
      if (!can(c,5)||!can(d,5)) {capacity++;continue;}
      next.set(c+","+d,[c,d]);
    }
    current=[...next.values()];
  }
  for (const [x,y] of current) {
    if ((x|y)!==ALL || (x&y)) throw Error("incomplete mask");
    final.set(x+","+y+","+zs.join(),{a:x.toString(16),b:y.toString(16),
                      pointsPositive:aa,pointsNegative:bb,zeros:zs});
  }
}
return {input:upstream.final.length,histogram,visits,direct,capacity,checks,final:[...final.values()]};

