const dotWide=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0n);
const monos=[[0,0],[1,1],[2,2],[0,1],[0,2],[1,2]];
const monomials=p=>monos.map(([i,j])=>p[i]*p[j]);
const pointRows=P.map(monomials);
const jets=G.map(([u,v])=>monos.map(([i,j])=>P[u][i]*P[v][j]+P[u][j]*P[v][i]));
const endpointBits=P.map((_,i)=>G.filter(([u])=>u===i).reduce((s,[,,b])=>s|b,0n));
const chamber = upstream.input===444;
if(!chamber && upstream.input!==317) throw Error("unexpected upstream scope");
const slopeRows=chamber
  ? [[0n,0n,68n,0n,3n,0n],[0n,0n,11n,0n,0n,1n],[0n,0n,31n,0n,1n,17n]]
  : [[0n,0n,0n,0n,1n,0n],[0n,0n,0n,0n,0n,1n]];
const compare=([a,b],[c,d])=>sg(a*d-b*c);
function solve1(rows) {
  let low=null,high=null;
  for (const {r:[a,b],strict} of rows) {
    if (!b) {
      if (a<0n || strict&&!a) return null;
      continue;
    }
    const bound={q:b>0n?[-a,b]:[a,-b],strict};
    const old=b>0n?low:high;
    const cmp=old?compare(bound.q,old.q):0;
    if (!old || b>0n&&cmp>0 || b<0n&&cmp<0 || !cmp&&strict) {
      if (b>0n) low=bound; else high=bound;
    }
  }
  if (!low&&!high) return [0n,1n];
  if (low&&!high) return [low.q[0]+low.q[1],low.q[1]];
  if (high&&!low) return [high.q[0]-high.q[1],high.q[1]];
  const cmp=compare(low.q,high.q);
  if (cmp>0 || !cmp&&(low.strict||high.strict)) return null;
  const [a,b]=low.q,[c,d]=high.q;
  return [a*d+b*c,2n*b*d];
}
function solve2(rows) {
  const pos=rows.filter(x=>x.r[2]>0n),neg=rows.filter(x=>x.r[2]<0n);
  const out=rows.filter(x=>!x.r[2]).map(x=>({r:x.r.slice(0,2),strict:x.strict}));
  for (const a of pos) for (const b of neg) {
    out.push({r:[0,1].map(j=>a.r[2]*b.r[j]-b.r[2]*a.r[j]),strict:a.strict||b.strict});
  }
  const x=solve1(out);
  if (!x) return null;
  const y=solve1(rows.map(({r,strict})=>({r:[r[0]*x[1]+r[1]*x[0],r[2]*x[1]],strict})));
  if (!y) throw Error("inconsistent elimination");
  return [x,y];
}
const results=[];
for(const {a:aa,b:bb,pointsPositive,pointsNegative,zeros} of upstream.final) {
  const a=BigInt("0x"+aa),b=BigInt("0x"+bb);
  const Pp=BigInt("0x"+pointsPositive),Pn=BigInt("0x"+pointsNegative);
  const signAt=P.map((_,i)=>endpointBits[i]&Pp?1n:endpointBits[i]&Pn?-1n:0n);
  if (signAt.map((s,i)=>s?-1:i).filter(i=>i>=0).join()!==zeros.join()) throw Error("zero provenance");
  let basis=Array.from({length:6},(_,i)=>Array.from({length:6},(_,j)=>i===j?1n:0n));
  for(const z of zeros) {
    const values=basis.map(x=>dotWide(pointRows[z],x));
    const p=values.findIndex(Boolean);
    if (p>=0) basis=basis.flatMap((x,i)=>i===p?[]:[
      norm(x.map((y,j)=>values[p]*y-values[i]*basis[p][j]))
    ]);
  }
  const pivot=basis.findIndex(v=>v[2]);
  if (pivot<0) {results.push({zeros,mask:aa+","+bb,feasible:false,reason:"c=0 forced"});continue;}
  const origin=scale(basis[pivot],BigInt(sg(basis[pivot][2])));
  const directions=basis.filter((_,i)=>i!==pivot).map(v=>norm(v.map((y,j)=>origin[2]*y-v[2]*origin[j])));
  const dimension=directions.length;
  if(dimension>2) throw Error("chart nearly unrestricted");
  while(directions.length<2) directions.push(Array(6).fill(0n));
  const chart=[origin,...directions];
  const rows=[];
  const add=(row,strict)=>rows.push({r:chart.map(x=>dotWide(x,row)),strict});
  for(const row of slopeRows) add(row,chamber);
  for(let i=0;i<P.length;i++) if(signAt[i]) add(scale(pointRows[i],signAt[i]),true);
  for(let i=0;i<G.length;i++) {
    const [u,v,bit]=G[i];
    if(signAt[u]) continue;
    const want=a&bit?1n:b&bit?-1n:0n;
    if(!want) throw Error("missing desired sign");
    add(scale(jets[i],want), signAt[v]!==want);
  }
  const witness=solve2(rows);
  if(!witness){results.push({zeros,mask:aa+","+bb,dimension,feasible:false});continue;}
  const [[x,X],[y,Y]]=witness;
  for(const {r:[a,b,c],strict} of rows) {
    const test=a*X*Y+b*x*Y+c*y*X;
    if(test<0n || strict&&!test) throw Error("invalid witness");
  }
  const q=origin.map((v,j)=>v*X*Y+directions[0][j]*x*Y+directions[1][j]*y*X);
  const [A,B,C,D,E,F]=q;
  const determinant8=2n*A*(4n*B*C-F*F)-D*(2n*C*D-E*F)+E*(D*F-2n*B*E);
  results.push({zeros,mask:aa+","+bb,dimension,feasible:true,witness:norm(q).map(String),
                determinant8:String(determinant8)});
}
return {results};
